package md.micb.qa.pages.components;

import md.micb.qa.pages.BasePage;
import org.openqa.selenium.By;
import org.openqa.selenium.TimeoutException;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;

import java.time.Duration;

/**
 * Cookiebot consent dialog. IDs are generated by the Cookiebot widget and are stable
 * across languages, unlike the button labels ("Respinge" / "Отклонить" / "Deny").
 */
public class CookieBanner extends BasePage {

    private static final By DIALOG = By.id("CybotCookiebotDialog");
    private static final By DECLINE = By.id("CybotCookiebotDialogBodyButtonDecline");
    private static final Duration APPEAR_TIMEOUT = Duration.ofSeconds(10);

    public boolean isDisplayed() {
        return !driver.findElements(DIALOG).isEmpty() && driver.findElement(DIALOG).isDisplayed();
    }

    /** Waits for the banner to appear; returns true if it was shown. */
    public boolean waitUntilShown() {
        try {
            new WebDriverWait(driver, APPEAR_TIMEOUT)
                    .until(ExpectedConditions.visibilityOfElementLocated(DECLINE));
            return true;
        } catch (TimeoutException e) {
            return false;
        }
    }

    /** Declines optional cookies (only strictly necessary cookies stay). */
    public void decline() {
        WebElement button = clickable(DECLINE);
        button.click();
        wait.withMessage("Cookie banner did not close after 'Decline'")
                .until(ExpectedConditions.invisibilityOfElementLocated(DIALOG));
        log.info("Optional cookies declined");
    }

    /** Precondition helper for scenarios that are not about cookies. */
    public void declineIfShown() {
        if (waitUntilShown()) {
            decline();
        }
    }

    /** Short check used after reload: the banner must stay hidden. */
    public boolean staysHidden(Duration period) {
        try {
            new WebDriverWait(driver, period)
                    .until(ExpectedConditions.visibilityOfElementLocated(DECLINE));
            return false;
        } catch (TimeoutException e) {
            return true;
        }
    }
}
